import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_conv_relu_bias_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_conv_relu_bias_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int in_channels,
    int out_channels,
    int kernel_size,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int stride,
    int padding,
    int dilation,
    int batch_size) {

    const int output_size = output_height * output_width;
    const int channel_size = input_height * input_width;
    const int weight_size = kernel_size * kernel_size;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * out_channels * output_size) return;

    int b = idx / (out_channels * output_size);
    int oc = (idx / output_size) % out_channels;
    int oh = (idx % output_size) / output_width;
    int ow = idx % output_width;

    float sum = 0.0f;

    for (int ic = 0; ic < in_channels; ic++) {
        for (int kh = 0; kh < kernel_size; kh++) {
            for (int kw = 0; kw < kernel_size; kw++) {
                int ih = oh * stride - padding + kh * dilation;
                int iw = ow * stride - padding + kw * dilation;

                if (ih >= 0 && ih < input_height && iw >= 0 && iw < input_width) {
                    int input_idx = b * in_channels * channel_size +
                                   ic * channel_size +
                                   ih * input_width +
                                   iw;

                    int weight_idx = oc * (in_channels * weight_size) +
                                    ic * weight_size +
                                    kh * kernel_size +
                                    kw;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    // ReLU + bias
    sum = fmaxf(sum + bias[oc], 0.0f);
    output[idx] = sum;
}

torch::Tensor fused_conv_relu_bias_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation) {

    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int input_height = input.size(2);
    const int input_width = input.size(3);
    const int out_channels = weight.size(0);
    const int kernel_size = weight.size(2);

    const int output_height = (input_height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    const int output_width = (input_width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, out_channels, output_height, output_width}, input.options());

    const int num_elements = batch_size * out_channels * output_height * output_width;
    const int block_size = 256;
    const int grid_size = (num_elements + block_size - 1) / block_size;

    fused_conv_relu_bias_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        in_channels,
        out_channels,
        kernel_size,
        input_height,
        input_width,
        output_height,
        output_width,
        stride,
        padding,
        dilation,
        batch_size);

    return output;
}
"""

fused_conv_relu_bias_cpp = "torch::Tensor fused_conv_relu_bias_cuda(torch::Tensor, torch::Tensor, torch::Tensor, int, int, int);"

fused_conv = load_inline(
    name='fused_conv',
    cpp_sources=fused_conv_relu_bias_cpp,
    cuda_sources=fused_conv_relu_bias_source,
    functions=['fused_conv_relu_bias_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, bias_shape):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = 1
        self.padding = kernel_size // 2
        self.dilation = 1

        self.weight = nn.Parameter(torch.randn(
            out_channels,
            in_channels,
            kernel_size,
            kernel_size
        ))
        self.bias = nn.Parameter(torch.randn(bias_shape))

    def forward(self, x):
        return fused_conv.fused_conv_relu_bias_cuda(
            x, 
            self.weight,
            self.bias.view(-1),
            self.stride,
            self.padding,
            self.dilation
        )
